examples.code:
// 1. Function declaration (hoisted)
function topla(a, b) {
    return a + b;
}

// 2. Function expression
const carp = function(a, b) {
    return a * b;
};

// 3. Arrow function
const bol = (a, b) => a / b;

// 4. Default parametreler
const selamla = (isim = 'Misafir') => `Merhaba, ${isim}!`;

function sayac() {
    let deger = 0;
    return {
        artir: () => ++deger,
        azalt: () => --deger,
        deger: () => deger,
    };
}

const c = sayac();
c.artir();
c.artir();
console.log(c.deger()); // 2
